import type { Source, SourceArgs } from "./Core";
/**
 * Callbag operator that limits the amount of data sent by a source.
 * Works on either pullable and listenable sources.
 *
 * Adapted from https://github.com/staltz/callbag-take
 *
 * Marble diagram:
 *   " a b c d |"
 *   {take(2)}
 *   " a b |"
 *
 * @param max The maximum number of items to take from the source.
 *     If there are less items in the source than max, the stream will end.
 *
 * @internal
 */
export declare const take: <T, E>(max: number) => (source: Source<T, E>) => (...sourceArgs: SourceArgs<T, E>) => void;
